// [UNITY-SKILL:SPRITEATLAS]
// [TYPE:PREBUILD]
// Generated by SpriteAtlas V2 Skill for WickFall
// Automatically packages and configures SpriteAtlas V2 assets during the prebuild pipeline

using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.U2D;
using UnityEngine;
using UnityEngine.U2D;

public class SpriteAtlasPrebuildGenerator : IPreprocessBuildWithReport
{
    public int callbackOrder => 0;

    public void OnPreprocessBuild(BuildReport report)
    {
        Debug.Log("[SpriteAtlas] Generating V2 atlases for WickFall...");

        // CRITICAL: Enable Sprite Packer V2 mode
        EditorSettings.spritePackerMode = SpritePackerMode.SpriteAtlasV2;

        // Generate Atlases for all core categories (Option A: Built-in data, includeInBuild=true)
        GenerateAtlasByFolder("Assets/Sprites/Characters", "Assets/Atlases/Characters_Atlas.spriteatlasv2", includeInBuild: true);
        GenerateAtlasByFolder("Assets/Sprites/Enemies", "Assets/Atlases/Enemies_Atlas.spriteatlasv2", includeInBuild: true);
        GenerateAtlasByFolder("Assets/Sprites/Props", "Assets/Atlases/Props_Atlas.spriteatlasv2", includeInBuild: true);
        GenerateAtlasByFolder("Assets/Sprites/Items", "Assets/Atlases/Items_Atlas.spriteatlasv2", includeInBuild: true);
        GenerateAtlasByFolder("Assets/Sprites/Environment", "Assets/Atlases/Environment_Atlas.spriteatlasv2", includeInBuild: true);
        GenerateAtlasByFolder("Assets/Sprites/UI", "Assets/Atlases/UI_Atlas.spriteatlasv2", includeInBuild: true);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
    }

    private bool IsValidProjectSprite(string assetPath)
    {
        return assetPath.StartsWith("Assets/") && !assetPath.Contains("/Packages/");
    }

    private void GenerateAtlasByFolder(string spriteFolder, string atlasPath, bool includeInBuild)
    {
        if (!Directory.Exists(spriteFolder))
        {
            Debug.LogWarning($"[SpriteAtlas] Folder not found: {spriteFolder}");
            return;
        }

        string[] guids = AssetDatabase.FindAssets("t:Sprite", new[] { spriteFolder });
        Object[] sprites = guids
            .Select(g => AssetDatabase.GUIDToAssetPath(g))
            .Where(path => IsValidProjectSprite(path))
            .Select(path => AssetDatabase.LoadAssetAtPath<Sprite>(path))
            .Where(s => s != null)
            .Cast<Object>()
            .ToArray();

        if (sprites.Length == 0)
        {
            Debug.LogWarning($"[SpriteAtlas] No sprites found in {spriteFolder}");
            return;
        }

        string dir = Path.GetDirectoryName(atlasPath);
        if (!Directory.Exists(dir))
        {
            Directory.CreateDirectory(dir);
        }

        SpriteAtlasAsset atlasAsset;
        if (File.Exists(atlasPath))
        {
            atlasAsset = SpriteAtlasAsset.Load(atlasPath);
            var spriteAtlas = AssetDatabase.LoadAssetAtPath<SpriteAtlas>(atlasPath);
            if (spriteAtlas != null)
            {
                atlasAsset.Remove(spriteAtlas.GetPackables());
            }
        }
        else
        {
            atlasAsset = new SpriteAtlasAsset();
        }

        atlasAsset.Add(sprites);
        SpriteAtlasAsset.Save(atlasAsset, atlasPath);
        AssetDatabase.ImportAsset(atlasPath);

        ConfigureAtlasImporter(atlasPath, includeInBuild);
        Debug.Log($"[SpriteAtlas] Successfully generated {atlasPath} with {sprites.Length} sprites (includeInBuild={includeInBuild})");
    }

    private void ConfigureAtlasImporter(string atlasPath, bool includeInBuild)
    {
        SpriteAtlasImporter importer = AssetImporter.GetAtPath(atlasPath) as SpriteAtlasImporter;
        if (importer == null) return;

        // Pixel-art settings: Point filtering and no mipmaps
        var textureSettings = importer.textureSettings;
        textureSettings.filterMode = FilterMode.Point;
        textureSettings.generateMipMaps = false;
        importer.textureSettings = textureSettings;

        // Pixel art packing settings: 2px padding, no rotation, no tight packing distortion
        var packingSettings = importer.packingSettings;
        packingSettings.padding = 2;
        packingSettings.enableTightPacking = false;
        packingSettings.enableRotation = false;
        packingSettings.enableAlphaDilation = false;
        importer.packingSettings = packingSettings;

        importer.includeInBuild = includeInBuild;
        importer.SaveAndReimport();
    }
}
